CREATE OR REPLACE FUNCTION public.admin_report_context(_type text,_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT public.has_role(auth.uid(),'admin') OR _id IS NULL OR _type NOT IN ('post','comment','conversation') THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF _type='post' THEN SELECT jsonb_build_object('post_id',p.id,'author_id',p.author_id,'email',a.email,'body',p.body,'title',p.title) INTO result FROM public.posts p JOIN public.profiles a ON a.id=p.author_id WHERE p.id=_id; ELSIF _type='comment' THEN SELECT jsonb_build_object('post_id',c.post_id,'author_id',c.author_id,'email',a.email,'body',c.body,'title',p.title) INTO result FROM public.comments c JOIN public.posts p ON p.id=c.post_id JOIN public.profiles a ON a.id=c.author_id WHERE c.id=_id; ELSE SELECT jsonb_build_object('conversation_id',c.id,'status',c.status,'sender',a.pseudonym,'sender_email',a.email,'recipient',b.pseudonym,'recipient_email',b.email) INTO result FROM public.conversations c JOIN public.profiles a ON a.id=c.sender_id JOIN public.profiles b ON b.id=c.recipient_id WHERE c.id=_id; END IF; IF result IS NULL THEN RAISE EXCEPTION 'Content not found'; END IF; INSERT INTO public.admin_actions(admin_id,action,target_type,target_id) VALUES(auth.uid(),'view_report_context',_type,_id); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.admin_report_context(text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_report_context(text,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.reaction_state(_post uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('kind',r.kind,'mine',r.user_id=auth.uid())),'[]'::jsonb) FROM public.reactions r WHERE r.post_id=_post AND (auth.uid() IS NULL OR NOT public.is_banned(auth.uid())) AND EXISTS(SELECT 1 FROM public.posts p WHERE p.id=_post AND NOT (p.is_deleted OR p.author_deleted OR p.admin_removed) AND (p.expires_at IS NULL OR p.expires_at>now())) $$;